-- LOT 24 - Fiches 141 a 143
START TRANSACTION;
UPDATE `conteneurs` SET
`description`='Container marittimo Dry 20DC di recente fabbricazione, riferimento produttore MIIU6639168, in acciaio Corten e colore bianco. Dotato di due porte scorrevoli posteriori chiudibili a chiave e tasche per carrello elevatore. La fonte indica la disponibilità del certificato CSC, da verificare sui documenti dell’unità. Adatto a trasporto marittimo, stoccaggio o allestimento, previa verifica di stato e idoneità. Disponibilità e condizioni di consegna sono confermate nel preventivo.',
`description_en`=COALESCE(NULLIF(`description_en`,''),'Recently manufactured Dry 20DC shipping container, manufacturer reference MIIU6639168, made of Corten steel and white. Fitted with two lockable rear sliding doors and forklift pockets. The source states that a CSC certificate is available; verify this against the unit’s documents. Suitable for shipping, storage or conversion, subject to checking condition and suitability. Availability and delivery terms are confirmed in the quotation.'),
`description_fr`=COALESCE(NULLIF(`description_fr`,''),'Conteneur maritime Dry 20DC de fabrication récente, référence fabricant MIIU6639168, en acier Corten et de couleur blanche. Équipé de deux portes coulissantes arrière verrouillables et de passages de fourches. La source indique qu’un certificat CSC est disponible; à vérifier dans les documents de l’unité. Adapté au transport maritime, au stockage ou à l’aménagement, sous réserve de vérifier l’état et l’adéquation. Disponibilité et conditions de livraison confirmées dans le devis.'),
`description_es`=COALESCE(NULLIF(`description_es`,''),'Contenedor marítimo Dry 20DC de fabricación reciente, referencia del fabricante MIIU6639168, de acero Corten y color blanco. Equipado con dos puertas correderas traseras con cerradura y alojamientos para horquillas. La fuente indica que dispone de certificado CSC; debe comprobarse en la documentación de la unidad. Adecuado para transporte marítimo, almacenamiento o acondicionamiento, previa comprobación del estado y la idoneidad. La disponibilidad y las condiciones de entrega se confirman en el presupuesto.'),
`description_de`=COALESCE(NULLIF(`description_de`,''),'Kürzlich gefertigter Dry-20DC-Schiffscontainer, Herstellerreferenz MIIU6639168, aus Cortenstahl und weiss. Mit zwei abschliessbaren hinteren Schiebetüren und Staplertaschen. Laut Quelle ist ein CSC-Zertifikat verfügbar; anhand der Unterlagen der Einheit prüfen. Geeignet für Seetransport, Lagerung oder Ausbau, vorbehaltlich Zustands- und Eignungsprüfung. Verfügbarkeit und Lieferbedingungen werden im Angebot bestätigt.'),
`description_nl`=COALESCE(NULLIF(`description_nl`,''),'Recent vervaardigde Dry 20DC-zeevaartcontainer, fabrikantreferentie MIIU6639168, van Cortenstaal en wit. Voorzien van twee afsluitbare schuifdeuren aan de achterzijde en heftruckopeningen. Volgens de bron is een CSC-certificaat beschikbaar; controleer dit in de documenten van de unit. Geschikt voor zeevervoer, opslag of inrichting, na controle van de staat en geschiktheid. Beschikbaarheid en leveringsvoorwaarden worden in de offerte bevestigd.'),
`description_fi`=COALESCE(NULLIF(`description_fi`,''),'Äskettäin valmistettu Dry 20DC -merikontti, valmistajan viite MIIU6639168, Corten-terästä ja valkoinen. Varusteina kaksi lukittavaa takaosan liukuovea ja trukkitaskut. Lähteen mukaan CSC-todistus on saatavilla; tarkista se yksikön asiakirjoista. Soveltuu merikuljetukseen, varastointiin tai muunneltavaksi, kun kunto ja soveltuvuus on tarkistettu. Saatavuus ja toimitusehdot vahvistetaan tarjouksessa.'),
`description_ch`=COALESCE(NULLIF(`description_ch`,''),'Kürzlich gefertigter Dry-20DC-Schiffscontainer, Herstellerreferenz MIIU6639168, aus Cortenstahl und weiss. Mit zwei abschliessbaren hinteren Schiebetüren und Staplertaschen. Laut Quelle ist ein CSC-Zertifikat verfügbar; anhand der Unterlagen der Einheit prüfen. Geeignet für Seetransport, Lagerung oder Ausbau, vorbehaltlich Zustands- und Eignungsprüfung. Verfügbarkeit und Lieferbedingungen werden im Angebot bestätigt.')
WHERE `id`=141 AND `reference`='CONT-MIIU-6639168';

UPDATE `conteneurs` SET
`description`='Offerta di noleggio container n. 109, colore giallo, dotato di tasche per carrello elevatore e porte chiudibili a chiave. Periodo minimo indicato nella descrizione: sei mesi. Canone indicato: 90 € + IVA al mese; periodi più brevi possono essere concordati. Disponibilità, importo aggiornato, durata e condizioni sono da confermare nel preventivo di noleggio.',
`description_en`=COALESCE(NULLIF(`description_en`,''),'Container rental offer no. 109, yellow, with forklift pockets and lockable doors. Minimum term stated in the description: six months. Stated rate: €90 + VAT per month; shorter terms may be agreed. Availability, current rate, term and conditions must be confirmed in the rental quotation.'),
`description_fr`=COALESCE(NULLIF(`description_fr`,''),'Offre de location de conteneur n° 109, jaune, avec passages de fourches et portes verrouillables. Durée minimale indiquée dans la description: six mois. Loyer annoncé: 90 € + TVA par mois; des périodes plus courtes peuvent être convenues. Disponibilité, tarif actualisé, durée et conditions sont à confirmer dans le devis de location.'),
`description_es`=COALESCE(NULLIF(`description_es`,''),'Oferta de alquiler de contenedor n.º 109, amarillo, con alojamientos para horquillas y puertas con cerradura. Plazo mínimo indicado en la descripción: seis meses. Tarifa indicada: 90 € + IVA al mes; se pueden acordar periodos más cortos. La disponibilidad, la tarifa actual, el plazo y las condiciones deben confirmarse en el presupuesto de alquiler.'),
`description_de`=COALESCE(NULLIF(`description_de`,''),'Container-Mietangebot Nr. 109, gelb, mit Staplertaschen und abschliessbaren Türen. In der Beschreibung angegebene Mindestlaufzeit: sechs Monate. Genannte Miete: 90 € zzgl. MwSt. pro Monat; kürzere Laufzeiten können vereinbart werden. Verfügbarkeit, aktueller Preis, Laufzeit und Bedingungen sind im Mietangebot zu bestätigen.'),
`description_nl`=COALESCE(NULLIF(`description_nl`,''),'Containerverhuuraanbod nr. 109, geel, met heftruckopeningen en afsluitbare deuren. In de beschrijving vermelde minimale huurtermijn: zes maanden. Vermelde huurprijs: € 90 + btw per maand; kortere periodes kunnen worden afgesproken. Beschikbaarheid, actuele huurprijs, looptijd en voorwaarden moeten in de huurofferte worden bevestigd.'),
`description_fi`=COALESCE(NULLIF(`description_fi`,''),'Kontin vuokraustarjous nro 109, keltainen, trukkitaskuilla ja lukittavilla ovilla. Kuvauksessa ilmoitettu vähimmäisvuokra-aika: kuusi kuukautta. Ilmoitettu vuokra: 90 € + ALV kuukaudessa; lyhyemmistä jaksoista voidaan sopia. Saatavuus, ajantasainen vuokra, kesto ja ehdot vahvistetaan vuokratarjouksessa.'),
`description_ch`=COALESCE(NULLIF(`description_ch`,''),'Container-Mietangebot Nr. 109, gelb, mit Staplertaschen und abschliessbaren Türen. In der Beschreibung angegebene Mindestlaufzeit: sechs Monate. Genannte Miete: 90 € zzgl. MwSt. pro Monat; kürzere Laufzeiten können vereinbart werden. Verfügbarkeit, aktueller Preis, Laufzeit und Bedingungen sind im Mietangebot zu bestätigen.')
WHERE `id`=142 AND `reference`='CONT-LOC-109';

UPDATE `conteneurs` SET
`description`='Container di stoccaggio nuovo, riferimento MIIU2252416, dimensioni esterne 2,44 x 2,20 x 2,26 m e dimensioni interne 2,28 x 2,11 x 2,05 m. Prodotto in acciaio e indicato per cortili o spazi commerciali. La descrizione afferma una resistenza agli agenti atmosferici di 50 anni; verificare le condizioni di garanzia applicabili.\n\nDotato di due porte con protezione centrale della serratura, punti di sollevamento rialzati, ventilazione laterale supplementare e possibilità di installare fino a tre serrature secondo la fonte. Le immagini sono dichiarate corrispondenti al prodotto. Noleggio e opzioni di pagamento sono menzionati.\n\nLa fonte cita trasporto e sollevamento con camion gru, side-loader o RAM e stoccaggio al terminal fino a sei mesi; servizi e durata vanno confermati. Disponibilità, prezzo, garanzia e condizioni di consegna sono definiti nel preventivo.',
`description_en`=COALESCE(NULLIF(`description_en`,''),'New storage container, reference MIIU2252416, external dimensions 2.44 x 2.20 x 2.26 m and internal dimensions 2.28 x 2.11 x 2.05 m. Made of steel and described for use in residential yards or commercial spaces. The source claims 50-year weather resistance; verify the applicable warranty terms.\n\nIt has two doors with central lock protection, raised lifting points, additional side ventilation and, according to the source, the option to fit up to three locks. The photos are stated to match the product. Rental and payment options are mentioned.\n\nThe source mentions transport and lifting by crane truck, side-loader or RAM and terminal storage for up to six months; services and duration must be confirmed. Availability, price, warranty and delivery terms are set out in the quotation.'),
`description_fr`=COALESCE(NULLIF(`description_fr`,''),'Conteneur de stockage neuf, référence MIIU2252416, dimensions extérieures de 2,44 x 2,20 x 2,26 m et dimensions intérieures de 2,28 x 2,11 x 2,05 m. En acier, présenté pour les cours résidentielles ou les espaces commerciaux. La source annonce une résistance aux intempéries de 50 ans; vérifier les conditions de garantie applicables.\n\nÉquipé de deux portes avec protection centrale de serrure, de points de levage surélevés, d’une ventilation latérale supplémentaire et, selon la source, de la possibilité d’installer jusqu’à trois cadenas. Les photos sont annoncées conformes au produit. Location et options de paiement sont mentionnées.\n\nLa source cite le transport et le levage par camion-grue, side-loader ou RAM ainsi que le stockage au terminal jusqu’à six mois; services et durée à confirmer. Disponibilité, prix, garantie et conditions de livraison sont définis dans le devis.'),
`description_es`=COALESCE(NULLIF(`description_es`,''),'Contenedor de almacenamiento nuevo, referencia MIIU2252416, dimensiones exteriores de 2,44 x 2,20 x 2,26 m e interiores de 2,28 x 2,11 x 2,05 m. Fabricado en acero y propuesto para patios residenciales o espacios comerciales. La fuente afirma una resistencia a la intemperie de 50 años; verifique las condiciones de garantía aplicables.\n\nDispone de dos puertas con protección central para la cerradura, puntos de elevación elevados, ventilación lateral adicional y, según la fuente, posibilidad de instalar hasta tres candados. Se indica que las fotos corresponden al producto. Se mencionan alquiler y opciones de pago.\n\nLa fuente cita transporte y elevación con camión grúa, side-loader o RAM y almacenamiento en terminal hasta seis meses; deben confirmarse los servicios y el plazo. La disponibilidad, el precio, la garantía y las condiciones de entrega se especifican en el presupuesto.'),
`description_de`=COALESCE(NULLIF(`description_de`,''),'Neuer Lagercontainer, Referenz MIIU2252416, Aussenmasse 2,44 x 2,20 x 2,26 m und Innenmasse 2,28 x 2,11 x 2,05 m. Aus Stahl gefertigt und laut Beschreibung für Wohnhöfe oder Gewerbeflächen vorgesehen. Die Quelle nennt 50 Jahre Witterungsbeständigkeit; geltende Garantiebedingungen prüfen.\n\nMit zwei Türen und mittigem Schlosschutz, erhöhten Hebepunkten, zusätzlicher Seitenbelüftung und laut Quelle der Möglichkeit, bis zu drei Schlösser anzubringen. Die Fotos sollen dem Produkt entsprechen. Miete und Zahlungsoptionen werden erwähnt.\n\nDie Quelle nennt Transport und Heben mit Kranwagen, Side-Loader oder RAM sowie Terminal-Lagerung bis zu sechs Monate; Leistungen und Dauer sind zu bestätigen. Verfügbarkeit, Preis, Garantie und Lieferbedingungen werden im Angebot festgelegt.'),
`description_nl`=COALESCE(NULLIF(`description_nl`,''),'Nieuwe opslagcontainer, referentie MIIU2252416, buitenmaten 2,44 x 2,20 x 2,26 m en binnenmaten 2,28 x 2,11 x 2,05 m. Van staal en volgens de beschrijving geschikt voor woonerven of commerciële ruimtes. De bron claimt 50 jaar weerbestendigheid; controleer de toepasselijke garantievoorwaarden.\n\nVoorzien van twee deuren met centrale slotbescherming, verhoogde hijspunten, extra zijventilatie en volgens de bron de mogelijkheid om maximaal drie sloten te plaatsen. De foto’s zouden overeenkomen met het product. Verhuur en betalingsopties worden genoemd.\n\nDe bron vermeldt transport en hijsen met kraanwagen, side-loader of RAM en terminalopslag tot zes maanden; diensten en termijn moeten worden bevestigd. Beschikbaarheid, prijs, garantie en leveringsvoorwaarden staan in de offerte.'),
`description_fi`=COALESCE(NULLIF(`description_fi`,''),'Uusi varastointikontti, viite MIIU2252416, ulkomitat 2,44 x 2,20 x 2,26 m ja sisämitat 2,28 x 2,11 x 2,05 m. Teräksinen yksikkö, jota kuvataan sopivaksi piha- tai liiketiloihin. Lähde ilmoittaa 50 vuoden säänkestävyyden; sovellettavat takuuehdot on tarkistettava.\n\nKaksi ovea, keskellä lukkosuoja, korotetut nostopisteet, lisätuuletus sivuilla ja lähteen mukaan mahdollisuus enintään kolmeen lukkoon. Kuvien ilmoitetaan vastaavan tuotetta. Vuokraus ja maksuvaihtoehdot mainitaan.\n\nLähde mainitsee kuljetuksen ja noston nosturiautolla, sivulastaajalla tai RAM-ajoneuvolla sekä terminaalivarastoinnin enintään kuudeksi kuukaudeksi; palvelut ja kesto on vahvistettava. Saatavuus, hinta, takuu ja toimitusehdot määritellään tarjouksessa.'),
`description_ch`=COALESCE(NULLIF(`description_ch`,''),'Neuer Lagercontainer, Referenz MIIU2252416, Aussenmasse 2,44 x 2,20 x 2,26 m und Innenmasse 2,28 x 2,11 x 2,05 m. Aus Stahl gefertigt und laut Beschreibung für Wohnhöfe oder Gewerbeflächen vorgesehen. Die Quelle nennt 50 Jahre Witterungsbeständigkeit; geltende Garantiebedingungen prüfen.\n\nMit zwei Türen und mittigem Schlosschutz, erhöhten Hebepunkten, zusätzlicher Seitenbelüftung und laut Quelle der Möglichkeit, bis zu drei Schlösser anzubringen. Die Fotos sollen dem Produkt entsprechen. Miete und Zahlungsoptionen werden erwähnt.\n\nDie Quelle nennt Transport und Heben mit Kranwagen, Side-Loader oder RAM sowie Terminal-Lagerung bis zu sechs Monate; Leistungen und Dauer sind zu bestätigen. Verfügbarkeit, Preis, Garantie und Lieferbedingungen werden im Angebot festgelegt.')
WHERE `id`=143 AND `reference`='MIIU2252416';
COMMIT;
